#include "../src/minibox-ipp/ipp.h"
#include <assert.h>
#include <string.h>
static int contains(const unsigned char*b,size_t n,const char*s){size_t z=strlen(s),i;if(z>n)return 0;for(i=0;i+z<=n;i++)if(!memcmp(b+i,s,z))return 1;return 0;}
static int contains_bytes(const unsigned char*b,size_t n,const unsigned char*v,size_t z){size_t i;if(z>n)return 0;for(i=0;i+z<=n;i++)if(!memcmp(b+i,v,z))return 1;return 0;}
int main(void){const unsigned char q[]={2,0,0,0x0b,0,0,0,7};const unsigned char create_op[]={0,0,0,5};const unsigned char send_op[]={0,0,0,6};struct ipp_request r;unsigned char z[4096];size_t n;assert(ipp_parse_header(q,sizeof q,&r)==0);assert(r.operation==IPP_OP_GET_PRINTER_ATTRIBUTES);assert(!strcmp(ipp_operation_name(IPP_OP_CREATE_JOB),"Create-Job"));assert(!strcmp(ipp_operation_name(IPP_OP_SEND_DOCUMENT),"Send-Document"));n=ipp_build_printer_attributes(z,sizeof z,&r,"ipp://minibox.local/ipp/print");assert(n>9);assert(contains(z,n,"operations-supported"));assert(contains_bytes(z,n,create_op,4));assert(contains_bytes(z,n,send_op,4));assert(contains(z,n,"image/pwg-raster"));n=ipp_build_job_attributes(z,sizeof z,&r,0,"ipp://minibox.local/ipp/print",7,3);assert(n>9);assert(contains(z,n,"job-id"));assert(contains(z,n,"job-uri"));assert(contains(z,n,"job-state"));return 0;}
